<template><view class="page-shell page-shell--tab conversations-page" :class="{'conversations-page--embedded':embedded}">
  <view class="conversation-heading"><view><text class="conversation-title">对话</text><text class="conversation-subtitle">与湖财人聊一聊</text></view><button class="conversation-new" @tap="start">＋ 发起对话</button></view>
  <view class="conversation-inbox surface" role="button" aria-label="消息与办理进度" @tap="open(signedIn?'/pages/inbox/index':'/pages/verify/index')"><view class="conversation-inbox-icon">信</view><view class="conversation-inbox-body"><view class="conversation-inbox-title"><text>消息与办理进度</text><text class="conversation-inbox-pin">置顶</text></view><text class="conversation-inbox-preview">{{ !signedIn?'登录后查看本人通知和办理记录':inboxError?'通知加载失败，点击进入重试':inboxLoading&&inboxUnread===null?'正在加载通知…':inboxLatest?.title||'暂无通知和办理记录' }}</text><text class="conversation-inbox-hint">通知、审核与服务状态集中到达</text></view><text v-if="inboxUnread" class="conversation-unread">{{ inboxUnread>99?'99+':inboxUnread }}</text><text v-else class="conversation-inbox-arrow">›</text></view>
  <view v-if="!signedIn" class="conversation-empty surface"><text class="conversation-empty-title">登录后开始对话</text><text>与校友私聊，或创建一个群聊</text><button class="primary-button" @tap="open('/pages/verify/index')">登录湖财人</button></view>
  <template v-else><view class="conversation-school-note"><text>学院、专业、班级群为系统固定群，按已核验学籍关联，不支持自行退出。</text><text @tap="open('/pages/profile/index')">查看个人资料 ›</text></view><view class="conversation-filter"><input v-model="keyword" placeholder="搜索已有对话" /></view><view v-if="error" class="conversation-error" role="alert">{{ error }}<text @tap="load">重试</text></view><view v-if="loading&&!items.length" class="conversation-empty surface">正在加载对话…</view>
  <view class="conversation-list surface" v-if="filtered.length"><view v-for="item in filtered" :key="item.id" class="conversation-item" @tap="open('/pages/chat/index?id='+item.id)"><view class="conversation-avatar" :class="{'conversation-avatar--group':item.type==='group'}">{{ item.type==='group'?'群':item.title.slice(-2) }}</view><view class="conversation-body"><view class="conversation-line"><view class="conversation-name-wrap"><text class="conversation-name">{{ conversationTitle(item) }}</text><text v-if="item.schoolGroup" class="conversation-school-tag">{{ schoolLabel(item.schoolGroup) }} · 固定群</text></view><text class="conversation-time">{{ date(item.updatedAt) }}</text></view><view class="conversation-line"><text class="conversation-preview">{{ item.status==='dissolved'?'群聊已解散':item.lastMessage?.text || '开始新的对话' }}</text><text v-if="item.unread" class="conversation-unread">{{ item.unread>99?'99+':item.unread }}</text></view></view></view></view>
  <view v-else-if="!loading&&!error" class="conversation-empty surface"><text class="conversation-empty-title">{{ keyword?'没有匹配的对话':'还没有对话' }}</text><text>点击“发起对话”，搜索校友或创建群聊。</text></view></template>
  <view v-if="creating" class="conversation-overlay" @tap.self="creating=false"><view class="conversation-dialog"><view class="conversation-dialog-head"><text>发起对话</text><button @tap="creating=false">关闭</button></view><view class="conversation-modes"><button :class="{active:type==='direct'}" @tap="type='direct';selected=[]">一对一私聊</button><button :class="{active:type==='group'}" @tap="type='group';selected=[]">创建群聊</button></view><text v-if="type==='group'" class="conversation-subtitle">自建群成员可退出；群主可在群成员面板解散群聊。</text><input v-if="type==='group'" class="conversation-input" v-model="groupName" maxlength="60" placeholder="群名称" /><view class="conversation-search"><input v-model="peopleQuery" placeholder="输入姓名或平台用户名" @confirm="search"/><button @tap="search">搜索</button></view><text class="conversation-subtitle">已选择 {{ selected.length }} 人{{ type==='group'?'（最多99人）':'' }}</text><scroll-view scroll-y class="conversation-people"><view v-for="p in people" :key="p.id" class="conversation-person" @tap="toggle(p)"><view><text>{{ p.name }}</text><text class="conversation-subtitle">{{ p.department }}</text></view><text>{{ selected.some(s=>s.id===p.id)?'☑':'＋' }}</text></view><text v-if="searched&&!people.length" class="conversation-subtitle">未找到符合条件的实名用户</text></scroll-view><text v-if="createError" class="conversation-error">{{ createError }}</text><button class="primary-button" :disabled="submitting||!selected.length" :loading="submitting" @tap="create">{{ type==='group'?'创建群聊':'开始私聊' }}</button></view></view>
  <SupportFooter v-if="!embedded" />
</view></template>
<script>
import { chatApi } from '../services/chat'
import { getMyInbox } from '../services/business'
import { getAccessToken,clearAuthState } from '../utils/store'
import { openPage } from '../utils/nav'
import { conversationTitle } from '../utils/chatGroups'
export default{
  props:{active:{type:Boolean,default:true},embedded:{type:Boolean,default:false}},
  emits:['conversation','navigate','unread'],
  watch:{active(value){if(value)this.activate();else this.stop()}},
  mounted(){if(this.active)this.activate()},beforeUnmount(){this.stop()},
  data:()=>({items:[],keyword:'',signedIn:false,error:'',loading:false,inboxLatest:null,inboxUnread:null,inboxLoading:false,inboxError:'',creating:false,type:'direct',groupName:'',peopleQuery:'',people:[],selected:[],searched:false,createError:'',submitting:false,generation:0,timer:null,sessionToken:''}),
  computed:{filtered(){return this.items.filter(i=>conversationTitle(i).includes(this.keyword.trim()))}},
  methods:{
    activate(){this.stop();if(!this.active)return;this.load();this.timer=setInterval(()=>this.load(),8000)},
    conversationTitle,
    schoolLabel(group){return ({college:'学院群',department:'学院群',major:'专业群',class:'班级群'})[group?.kind]||'学籍群'},
    open(path){if(this.embedded){const match=/^\/pages\/chat\/index\?id=([^&]+)/.exec(path);if(match){this.$emit('conversation',decodeURIComponent(match[1]));return}this.$emit('navigate',path)}openPage(path)},date(v){return new Date(v).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})},
    stop(){this.generation++;clearInterval(this.timer);this.loading=false;this.inboxLoading=false;this.submitting=false},
    valid(g,t){return g===this.generation&&t===getAccessToken()},
    reset(token){this.sessionToken=token;this.items=[];this.inboxLatest=null;this.inboxUnread=null;this.inboxLoading=false;this.inboxError='';this.selected=[];this.people=[];this.peopleQuery='';this.groupName='';this.creating=false;this.loading=false;this.submitting=false;this.signedIn=!!token;this.$emit?.('unread',0);uni.removeTabBarBadge({index:2})},
    begin(){const token=getAccessToken();if(!token||token!==this.sessionToken){this.generation++;this.reset(token);return null}return {token,g:this.generation}},
    emitUnread(){const count=this.items.reduce((n,x)=>n+Number(x.unread||0),0)+Number(this.inboxUnread||0);this.$emit?.('unread',count);if(count)uni.setTabBarBadge({index:2,text:count>99?'99+':String(count)});else uni.removeTabBarBadge({index:2})},
    async loadInboxSummary(g,token){if(!token||this.inboxLoading)return;this.inboxLoading=true;try{const result=await getMyInbox({page:1,pageSize:1},{token});if(!this.valid(g,token))return;this.inboxLatest=result.items?.[0]||null;this.inboxUnread=Math.max(0,Number(result.unread)||0);this.inboxError='';this.emitUnread()}catch(error){if(this.valid(g,token)){this.inboxError=error.message||'通知加载失败';if([401,403].includes(error.statusCode)){this.inboxLatest=null;this.inboxUnread=null;this.emitUnread()}}}finally{if(this.valid(g,token))this.inboxLoading=false}},
    async load(){const token=getAccessToken();if(token!==this.sessionToken){this.generation++;this.reset(token)}const g=this.generation;this.signedIn=!!token;if(!token||this.loading)return;this.loading=true;const inboxTask=this.loadInboxSummary(g,token);try{const r=await chatApi('/conversations',{token});if(!this.valid(g,token))return;this.items=r.items;this.error='';this.emitUnread()}catch(e){if(this.valid(g,token)){this.error=e.message;if(e.statusCode===401){clearAuthState();this.reset('')}}}finally{if(this.valid(g,token))this.loading=false;await inboxTask}},
    start(){if(!this.begin()){openPage('/pages/verify/index');return}this.creating=true;this.createError=''},
    async search(){const s=this.begin();if(!s)return;this.createError='';const q=this.peopleQuery;try{const r=await chatApi('/people?query='+encodeURIComponent(q),{token:s.token});if(!this.valid(s.g,s.token)||q!==this.peopleQuery)return;this.people=r.items;this.searched=true}catch(e){if(this.valid(s.g,s.token))this.createError=e.message}},
    toggle(p){if(!this.begin())return;if(this.type==='direct'){this.selected=[p];return}if(this.selected.some(x=>x.id===p.id))this.selected=this.selected.filter(x=>x.id!==p.id);else if(this.selected.length<99)this.selected.push(p)},
    async create(){const s=this.begin();if(!s||this.submitting)return;this.submitting=true;this.createError='';try{const c=await chatApi('/conversations',{method:'POST',token:s.token,data:{type:this.type,title:this.groupName,memberIds:this.selected.map(p=>p.id)}});if(!this.valid(s.g,s.token))return;this.creating=false;this.selected=[];this.open('/pages/chat/index?id='+c.id)}catch(e){if(this.valid(s.g,s.token))this.createError=e.message}finally{if(this.valid(s.g,s.token))this.submitting=false}}
  }
}
</script>
<style scoped>
.conversations-page{max-width:1000px;padding-top:24px}.conversation-heading,.conversation-line,.conversation-dialog-head,.conversation-person{display:flex;justify-content:space-between;align-items:center;gap:12px}.conversation-heading{margin-bottom:24px}.conversation-title{font-size:28px;font-weight:700}.conversation-subtitle{display:block;font-size:14px;color:#7b889a;line-height:1.6;margin-top:5px}.conversation-new{margin:0;background:#033481;color:#fff;border-radius:12px;padding:0 15px;line-height:44px;font-size:15px}.conversation-filter input,.conversation-input,.conversation-search{background:white;border:1px solid #dde4ef;border-radius:12px;padding:12px 16px;font-size:16px;margin-bottom:20px;height:48px}.conversation-empty{padding:40px 24px;text-align:center;font-size:15px;line-height:1.8;color:#768397}.conversation-empty-title{display:block;font-size:20px;font-weight:600;color:#233751;margin-bottom:10px}.conversation-empty button{margin-top:22px;font-size:16px}.conversation-list{padding:0 20px}.conversation-item{display:flex;gap:14px;padding:22px 0;border-bottom:1px solid #edf0f5}.conversation-item:last-child{border:0}.conversation-avatar{width:52px;height:52px;background:#e5edfa;color:#033481;border-radius:16px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-weight:650;font-size:19px}.conversation-avatar--group{background:#e2f2ec;color:#176551}.conversation-body{min-width:0;flex:1}.conversation-name{font-size:17px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation-time{font-size:12px;color:#8592a5;white-space:nowrap}.conversation-preview{margin-top:9px;font-size:14px;color:#7c899b;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.conversation-unread{font-size:12px;background:#ba4545;color:#fff;padding:2px 7px;border-radius:12px}.conversation-error{display:block;color:#a33d32;font-size:14px;line-height:1.6;margin:12px 0}.conversation-error>text{margin-left:20px;color:#033481}.conversation-overlay{position:fixed;inset:0;background:rgba(7,28,60,.4);z-index:999;display:flex;align-items:center;justify-content:center;padding:20px}.conversation-dialog{width:100%;max-width:520px;max-height:85vh;overflow:auto;border-radius:22px;background:#fff;padding:24px}.conversation-dialog-head{font-size:22px;font-weight:650;margin-bottom:16px}.conversation-dialog-head button,.conversation-search button{font-size:14px;background:transparent;color:#033481;margin:0;padding:0 5px}.conversation-modes{display:flex;gap:10px;margin-bottom:18px}.conversation-modes button{flex:1;font-size:15px;line-height:44px;border-radius:10px;background:#f0f4fa}.conversation-modes .active{color:#fff;background:#033481}.conversation-search{display:flex;align-items:center;gap:10px}.conversation-search input{flex:1;min-width:0}.conversation-people{height:230px;margin:15px 0}.conversation-person{padding:12px 0;border-bottom:1px solid #eef1f5;font-size:16px}.conversation-dialog>.primary-button{font-size:16px;height:48px;line-height:48px}
</style>
<style scoped>
.conversation-inbox{display:flex;align-items:center;gap:14px;padding:18px;margin-bottom:18px;border:1px solid #e7dfd0;background:#fffcf5;cursor:pointer}.conversation-inbox-icon{width:48px;height:48px;flex-shrink:0;display:flex;align-items:center;justify-content:center;border-radius:14px;background:#f4e4c1;color:#866328;font-size:21px;font-weight:650}.conversation-inbox-body{flex:1;min-width:0}.conversation-inbox-title{display:flex;align-items:center;flex-wrap:wrap;gap:7px;font-size:16px;font-weight:650;color:#4f483b}.conversation-inbox-pin{font-size:10px;font-weight:400;background:#ece6d8;padding:1px 5px;border-radius:4px;color:#867456}.conversation-inbox-preview{display:block;margin-top:7px;font-size:14px;color:#665f52;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.conversation-inbox-hint{display:block;margin-top:5px;color:#9a907e;font-size:12px;line-height:1.5}.conversation-inbox-arrow{font-size:22px;color:#9b8a69}.conversations-page--embedded .conversation-inbox{gap:8px;padding:12px 10px;border-radius:12px;margin-bottom:12px}.conversations-page--embedded .conversation-inbox-icon{width:34px;height:38px;font-size:16px;border-radius:10px}.conversations-page--embedded .conversation-inbox-title{font-size:13px;gap:4px}.conversations-page--embedded .conversation-inbox-preview{font-size:12px}.conversations-page--embedded .conversation-inbox-hint{font-size:10px}
.conversation-school-note{display:flex;flex-wrap:wrap;gap:7px 16px;margin-bottom:18px;padding:12px 15px;border-radius:12px;background:#eaf3fa;color:#5a7390;font-size:13px;line-height:1.7}.conversation-school-note>text:last-child{color:#174c86}.conversation-name-wrap{min-width:0;flex:1;display:flex;align-items:center;gap:7px;flex-wrap:wrap}.conversation-school-tag{font-size:11px;line-height:1.6;padding:2px 6px;background:#e9f5ef;color:#27654e;border-radius:5px;white-space:nowrap}
</style>

<style scoped>
.conversations-page--embedded{height:100%;min-height:0;overflow:auto;padding:16px!important;max-width:none;margin:0;background:#f7f9fc;font-size:14px}.conversations-page--embedded .conversation-heading{align-items:flex-start;gap:8px;margin-bottom:14px}.conversations-page--embedded .conversation-title{font-size:20px}.conversations-page--embedded .conversation-subtitle{font-size:12px}.conversations-page--embedded .conversation-new{font-size:12px;line-height:34px;padding:0 10px;border-radius:8px;white-space:nowrap}.conversations-page--embedded .conversation-school-note{padding:9px 10px;font-size:11px;margin-bottom:12px}.conversations-page--embedded .conversation-school-note>text:last-child{display:none}.conversations-page--embedded .conversation-filter input{font-size:13px;height:38px;margin-bottom:12px;padding:9px 10px}.conversations-page--embedded .conversation-list{padding:0 10px;border-radius:12px}.conversations-page--embedded .conversation-item{gap:9px;padding:15px 0;cursor:pointer}.conversations-page--embedded .conversation-avatar{width:38px;height:38px;font-size:14px;border-radius:10px}.conversations-page--embedded .conversation-name{font-size:14px}.conversations-page--embedded .conversation-time{font-size:10px}.conversations-page--embedded .conversation-preview{font-size:12px;max-width:170px}.conversations-page--embedded .conversation-empty{padding:26px 12px;font-size:13px}.conversations-page--embedded .conversation-overlay{position:absolute;z-index:8;padding:18px}.conversations-page--embedded .conversation-dialog{max-height:100%;padding:20px}.conversations-page--embedded .conversation-people{height:180px}.conversations-page--embedded .conversation-dialog-head{font-size:18px}
</style>
